import ballerina/io;

int v = 1;

function bump() returns int {
    v = 99;
    return 2;
}

function pair(int a, int b) returns int[] {
    return [a, b];
}

public function main() {
    map<int> m = {x: v, y: bump()};
    io:println(m);

    v = 1;
    int[] l = [v, bump()];
    io:println(l);

    v = 1;
    io:println(pair(v, bump()));

    v = 1;
    io:println(v + bump());

    int local = 1;
    var change = function() returns int {
        local = 99;
        return 2;
    };
    int[] c = [local, change()];
    io:println(c);
}

import ballerina/io;

type Extra record {
    never name?;
    never extra?;
};

function describe(string name, *Extra extra) returns string {
    return name + " " + extra.toString();
}

public function main() {
    io:println(describe("a", count = 3)); // @output a {"count":3}
    io:println(describe("b")); // @output b {}
}
